package com.testora.dao;
import com.testora.config.DBConnection; import com.testora.model.*; import java.sql.*; import java.util.*;
/** CRUD repository for problems and their testcases. */
public class ProblemDAO implements CrudDAO<Problem,Long>{
 private Problem map(ResultSet r)throws SQLException{Problem p=new Problem(r.getLong("id"),r.getString("title"),r.getString("slug"),r.getString("description"),r.getString("difficulty"),r.getString("starter_code"),r.getLong("topic_id"),r.getInt("time_limit_sec"),r.getInt("max_marks"));p.setTopicName(r.getString("topic_name"));return p;}
 public Problem create(Problem p)throws SQLException{String q="INSERT INTO problems(title,slug,description,difficulty,starter_code,topic_id,time_limit_sec,max_marks) VALUES(?,?,?,?,?,?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){fill(s,p);s.executeUpdate();try(ResultSet k=s.getGeneratedKeys()){k.next();p.setId(k.getLong(1));}return p;}}
 private void fill(PreparedStatement s,Problem p)throws SQLException{s.setString(1,p.getTitle());s.setString(2,p.getSlug());s.setString(3,p.getDescription());s.setString(4,p.getDifficulty());s.setString(5,p.getStarterCode());s.setLong(6,p.getTopicId());s.setInt(7,p.getTimeLimitSec());s.setInt(8,p.getMaxMarks());}
 public Optional<Problem> findById(Long id)throws SQLException{return queryOne("SELECT p.*,t.topic_name FROM problems p JOIN topics t ON p.topic_id=t.id WHERE p.id=?",id);}
 private Optional<Problem> queryOne(String q,Object value)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setObject(1,value);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}}
 public List<Problem> findAll()throws SQLException{return query("SELECT p.*,t.topic_name FROM problems p JOIN topics t ON p.topic_id=t.id ORDER BY p.title",null);}
 public List<Problem> query(String q,Object value)throws SQLException{List<Problem>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(q)){if(value!=null)s.setObject(1,value);try(ResultSet r=s.executeQuery()){while(r.next())a.add(map(r));}}return a;}
 public boolean update(Problem p)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("UPDATE problems SET title=?,slug=?,description=?,difficulty=?,starter_code=?,topic_id=?,time_limit_sec=?,max_marks=? WHERE id=?")){fill(s,p);s.setLong(9,p.getId());return s.executeUpdate()>0;}}
 public boolean delete(Long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("DELETE FROM problems WHERE id=?")){s.setLong(1,id);return s.executeUpdate()>0;}}
 public List<TestCase> testCases(long id,boolean includeHidden)throws SQLException{String q="SELECT * FROM problem_testcases WHERE problem_id=?"+(includeHidden?"":" AND is_hidden=false");List<TestCase>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){while(r.next())a.add(new TestCase(r.getLong("id"),id,r.getString("input"),r.getString("expected_output"),r.getBoolean("is_hidden")));}}return a;}
 public void replaceTests(long id,List<TestCase> tests)throws SQLException{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement d=c.prepareStatement("DELETE FROM problem_testcases WHERE problem_id=?");PreparedStatement i=c.prepareStatement("INSERT INTO problem_testcases(problem_id,input,expected_output,is_hidden) VALUES(?,?,?,?)")){d.setLong(1,id);d.executeUpdate();for(TestCase t:tests){i.setLong(1,id);i.setString(2,t.input());i.setString(3,t.expectedOutput());i.setBoolean(4,t.hidden());i.addBatch();}i.executeBatch();c.commit();}catch(SQLException e){c.rollback();throw e;}}}
 public List<Topic> topics()throws SQLException{List<Topic>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("SELECT * FROM topics ORDER BY topic_name");ResultSet r=s.executeQuery()){while(r.next())a.add(new Topic(r.getLong(1),r.getString(2)));}return a;}
}
